const parseBday = s => { const m = String(s || '').match(/^M(\d{1,2}) W([1-4]) (Mon|Tue|Wed|Thu|Fri|Sat|Sun)$/); return m ? { m: +m[1], w: +m[2], d: m[3] } : { m: 0, w: 1, d: 'Mon' }; };
