// the final assistant message, so put a tool edit immediately BEFORE that message when there is one. Its floor is computed
// from the pre-reply state: a swipe can then discard/recompute the reply without inheriting the rejected reply's changes.
// Keep the current edited state on the existing reply for normal continuation. With no final assistant, append as before.
// 1.11.1: every player-tool patch says so, and the engine does not count it as a story turn (the Fortune roll stays)
const TOOL_OP = { op: 'replace', path: '/$eng/tool', value: 1 };
async function writeToolMessage(text, next) {
  const last = getLastMessageId();
  const tail = getChatMessages(last)[0];
  let insertBefore = null, toolState = next;
  if (tail && tail.role === 'assistant' && !tail.is_hidden && last > 0) {
    for (let i = last - 1; i >= 0; i--) {
      const prior = getVariables({ type: 'message', message_id: i });
      if (prior && prior.stat_data && prior.stat_data.World) {
        const parsed = await Mvu.parseMessage(text, _.cloneDeep(prior));
        if (!parsed || !parsed.stat_data) throw new Error('MVU could not prepare the edit for a swipe. Nothing was saved.');
        toolState = parsed;
        insertBefore = last;
        break;
      }
    }
  }
  await createChatMessages([{ role: 'user', message: text, is_hidden: true, data: toolState }],
    insertBefore === null ? { refresh: 'none' } : { insert_before: insertBefore, refresh: 'none' });
  if (insertBefore !== null) {
    await Mvu.replaceMvuData(toolState, { type: 'message', message_id: insertBefore });
    await Mvu.replaceMvuData(next, { type: 'message', message_id: insertBefore + 1 });
    await setChatMessages([{ message_id: insertBefore }, { message_id: insertBefore + 1 }], { refresh: 'all' });
  } else {
    const id = getLastMessageId();
    await Mvu.replaceMvuData(next, { type: 'message', message_id: id });
    await setChatMessages([{ message_id: id }], { refresh: 'affected' });
  }
  try { if (SillyTavern && typeof SillyTavern.saveChat === 'function') await SillyTavern.saveChat(); } catch (e) { console.warn('[Eldrasil UI] save', e); }
}
